// A -- B,  A -- C,  B -- C
const graph = {
  A: ["B", "C"],
  B: ["A", "C"],
  C: ["A", "B"],
};

// Undirected means you store the edge twice, once from each end.
// Forgetting the second one is the most common graph bug there is.

for (const neighbour of graph["A"]) {
  console.log(neighbour); // B, then C
}

