function buildUndirected(nodes, edges) {
  const adj = new Map(nodes.map((n) => [n, []]));
  for (const [from, to] of edges) {
    adj.get(from).push(to);
    adj.get(to).push(from); // <- the line people forget
  }
  return adj;
}

