#include <map>
#include <string>
#include <utility>
#include <vector>

std::map<std::string, std::vector<std::string>> buildUndirected(
    const std::vector<std::string>& nodes,
    const std::vector<std::pair<std::string, std::string>>& edges) {
    std::map<std::string, std::vector<std::string>> adj;
    for (const std::string& n : nodes) adj[n] = {};

    for (const auto& [from, to] : edges) {
        adj[from].push_back(to);
        adj[to].push_back(from);  // <- the line people forget
    }
    return adj;
}
